bounded_host_request.command:
set -euo pipefail
old="$(docker image inspect -f '{{.Id}}' gace-tgtumbler-gaybbs:link-pr62-4a1c5be3)" || exit 61
live="$(docker inspect -f '{{.Image}}' deploy-gaybbs-1)" || exit 62
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true || exit 63
test "$live" = "$old" || exit 64
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 65
docker exec deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import fs from "node:fs";
const p=process.env.BOT_TOKEN_FILE;
const token=p?fs.readFileSync(p,"utf8").trim():process.env.BOT_TOKEN;
if(!token)process.exit(71);
let passed=false;
for(let i=0;i<3;i++){
try{const r=await fetch("https://api.telegram.org/bot"+token+"/getMe",{signal:AbortSignal.timeout(16000)});const j=await r.json();if(j.ok&&j.result.username==="GayBBS_bot"){passed=true;break;}}catch{}
}
if(!passed)process.exit(72);
' || exit 66
echo PREVIOUS_LINK_IMAGE_ROLLBACK=PASS
echo BOT_API_HEALTH_RETRY=PASS
echo USERBOT_ACTIVE=PASS
